Here is the commit message:
rxrpc: Fix missing validation of ticket length in non-XDR key
 preparsing

In rxrpc_preparse(), there are two paths for parsing key payloads: the
XDR path (for large payloads) and the non-XDR path (for payloads <= 28
bytes). While the XDR path (rxrpc_preparse_xdr_rxkad()) correctly
validates the ticket length against AFSTOKEN_RK_TIX_MAX, the non-XDR
path fails to do so.

This allows an unprivileged user to provide a very large ticket length.
When this key is later read via rxrpc_read(), the total
token size (toksize) calculation results in a value that exceeds
AFSTOKEN_LENGTH_MAX, triggering a WARN_ON().

[ 2001.302904] WARNING: CPU: 2 PID: 2108 at net/rxrpc/key.c:778 rxrpc_read+0x109/0x5c0 [rxrpc]

Fix this by adding a check in the non-XDR parsing path of rxrpc_preparse()
to ensure the ticket length does not exceed AFSTOKEN_RK_TIX_MAX,
bringing it into parity with the XDR parsing logic.

Fixes: 8a7a3eb4ddbe ("KEYS: RxRPC: Use key preparsing")
Fixes: 84924aac08a4 ("rxrpc: Fix checker warning")
Reported-by: Anderson Nascimento <anderson@allelesecurity.com>
Signed-off-by: Anderson Nascimento <anderson@allelesecurity.com>
Signed-off-by: David Howells <dhowells@redhat.com>
cc: Marc Dionne <marc.dionne@auristor.com>
cc: Jeffrey Altman <jaltman@auristor.com>
cc: Simon Horman <horms@kernel.org>
cc: linux-afs@lists.infradead.org
cc: stable@kernel.org
Link: https://patch.msgid.link/20260422161438.2593376-7-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In `rxrpc_preparse()`, the non-XDR parsing path fails to validate that `v1->ticket_length` does not exceed `AFSTOKEN_RK_TIX_MAX`, unlike the XDR path. This allows an unprivileged user to provide an oversized ticket length, leading to a token size calculation (`toksize`) that exceeds `AFSTOKEN_LENGTH_MAX`, which triggers a `WARN_ON()` when the key is later read via `rxrpc_read()`.

Here is the patch:
  */
 static int rxrpc_preparse(struct key_preparsed_payload *prep)
 {
 	const struct rxrpc_key_data_v1 *v1;
 	struct rxrpc_key_token *token, **pp;
 	time64_t expiry;
 	size_t plen;
 	u32 kver;
 	int ret;

 	_enter("%zu", prep->datalen);

 	/* handle a no-security key */
 	if (!prep->data && prep->datalen == 0)
 		return 0;

 	/* determine if the XDR payload format is being used */
 	if (prep->datalen > 7 * 4) {
 		ret = rxrpc_preparse_xdr(prep);
 		if (ret != -EPROTO)
 			return ret;
 	}

 	/* get the key interface version number */
 	ret = -EINVAL;
 	if (prep->datalen <= 4 || !prep->data)
 		goto error;
 	memcpy(&kver, prep->data, sizeof(kver));
 	prep->data += sizeof(kver);
 	prep->datalen -= sizeof(kver);
 	prep->quotalen = 0;

 	_debug("KEY I/F VERSION: %u", kver);

 	ret = -EKEYREJECTED;
 	if (kver != 1)
 		goto error;

 	/* deal with a version 1 key */
 	ret = -EINVAL;
 	if (prep->datalen < sizeof(*v1))
 		goto error;

 	v1 = prep->data;
 	if (prep->datalen != sizeof(*v1) + v1->ticket_length)
 		goto error;

 	_debug("SCIX: %u", v1->security_index);
 	_debug("TLEN: %u", v1->ticket_length);
 	_debug("EXPY: %x", v1->expiry);
 	_debug("KVNO: %u", v1->kvno);
 	_debug("SKEY: %02x%02x%02x%02x%02x%02x%02x%02x",
 	       v1->session_key[0], v1->session_key[1],
 	       v1->session_key[2], v1->session_key[3],
 	       v1->session_key[4], v1->session_key[5],
 	       v1->session_key[6], v1->session_key[7]);
 	if (v1->ticket_length >= 8)
 		_debug("TCKT: %02x%02x%02x%02x%02x%02x%02x%02x",
 		       v1->ticket[0], v1->ticket[1],
 		       v1->ticket[2], v1->ticket[3],
 		       v1->ticket[4], v1->ticket[5],
 		       v1->ticket[6], v1->ticket[7]);

 	ret = -EPROTONOSUPPORT;
 	if (v1->security_index != RXRPC_SECURITY_RXKAD)
 		goto error;

+	ret = -EKEYREJECTED;
+	if (v1->ticket_length > AFSTOKEN_RK_TIX_MAX)
+		goto error;
+
 	plen = sizeof(*token->kad) + v1->ticket_length;
 	prep->quotalen += plen + sizeof(*token);

 	ret = -ENOMEM;
 	token = kzalloc_obj(*token);
 	if (!token)
 		goto error;
 	token->kad = kzalloc(plen, GFP_KERNEL);
 	if (!token->kad)
 		goto error_free;

 	token->security_index		= RXRPC_SECURITY_RXKAD;
 	token->kad->ticket_len		= v1->ticket_length;
 	token->kad->expiry		= v1->expiry;
 	token->kad->kvno		= v1->kvno;
 	memcpy(&token->kad->session_key, &v1->session_key, 8);
 	memcpy(&token->kad->ticket, v1->ticket, v1->ticket_length);

 	/* count the number of tokens attached */
 	prep->payload.data[1] = (void *)((unsigned long)prep->payload.data[1] + 1);

 	/* attach the data */
 	pp = (struct rxrpc_key_token **)&prep->payload.data[0];
 	while (*pp)
 		pp = &(*pp)->next;
 	*pp = token;
 	expiry = rxrpc_u32_to_time64(token->kad->expiry);
 	if (expiry < prep->expiry)
 		prep->expiry = expiry;
 	token = NULL;
 	ret = 0;

 error_free:
 	kfree(token);
 error:
 	return ret;
 }



